using Mindweave.Core.Conversations;
using Mindweave.Core.Models;

namespace Mindweave.Application.Ai;

public enum ChatRole
{
    System,
    User,
    Assistant,

    /// <summary>A tool's result handed back to the model (phase 2); <see cref="ChatTurn.ToolCallId"/> names the call.</summary>
    Tool,
}

/// <summary>
/// A tool call as the model made it (architecture §15.6): its ID (generated by the adapter when the service gave none), the
/// tool's name and the arguments as JSON text. <paramref name="ArgumentsValid"/> is false when the arguments are not a JSON
/// object; the run then hands the error back to the model.
/// </summary>
public sealed record ChatToolCall(string Id, string Name, string Arguments, bool ArgumentsValid = true);

/// <summary>A tool offered to the model: its name, what it does, and the JSON Schema of its input (as JSON text).</summary>
public sealed record ChatTool(string Name, string Description, string ParametersSchema);

/// <summary>An image sent as a part of a user turn (architecture §15.4): its media type and bytes, sent as a data URL.</summary>
public sealed record ChatImage(string MediaType, byte[] Data);

/// <summary>
/// One turn. <paramref name="Images"/> go with a user turn only, and only to a model that declares
/// <see cref="ModelCapability.ImageInput"/>; an adapter sends them as image parts after <paramref name="Content"/>.
/// </summary>
/// <remarks>
/// In a run (phase 2): an assistant turn may carry the <see cref="ToolCalls"/> it made (its <see cref="Content"/> is the text
/// written before them, possibly empty) and the <see cref="Reasoning"/> the service sent with them, which some services
/// require back in later requests of the same run (decision R10: kept in memory only, never stored); a
/// <see cref="ChatRole.Tool"/> turn carries one result for <see cref="ToolCallId"/>.
/// </remarks>
public sealed record ChatTurn(ChatRole Role, string Content, IReadOnlyList<ChatImage>? Images = null)
{
    public bool HasImages => Images is { Count: > 0 };

    public IReadOnlyList<ChatToolCall>? ToolCalls { get; init; }

    public string? ToolCallId { get; init; }

    public string? Reasoning { get; init; }
}

public static class ChatTurns
{
    /// <summary>The estimate of a request as sent: its texts plus a fixed cost per image (architecture §15.4).</summary>
    public static int Estimate(IReadOnlyList<ChatTurn> turns)
    {
        ArgumentNullException.ThrowIfNull(turns);
        return Core.Context.TokenEstimator.Request(turns.Select(t => t.ToolCalls is { Count: > 0 } calls ? t.Content + string.Concat(calls.Select(c => c.Name + c.Arguments)) : t.Content))
            + (turns.Sum(t => t.Images?.Count ?? 0) * Core.Context.ResourceMaterial.ImageTokens);
    }

    /// <summary>The estimate of a request with its tool definitions.</summary>
    public static int Estimate(ChatRequest request)
    {
        ArgumentNullException.ThrowIfNull(request);
        return Estimate(request.Turns) + (request.Tools?.Sum(Estimate) ?? 0);
    }

    /// <summary>The estimate of one tool definition.</summary>
    public static int Estimate(ChatTool tool)
    {
        ArgumentNullException.ThrowIfNull(tool);
        return Core.Context.TokenEstimator.Estimate(tool.Name + tool.Description + tool.ParametersSchema);
    }
}

/// <summary>
/// Provider-neutral request. Adapters translate it; no SDK types cross this boundary. <see cref="Tools"/> are offered only to
/// a model that declares <see cref="ModelCapability.ToolCalls"/>, always with the service choosing (<c>tool_choice: "auto"</c>).
/// </summary>
public sealed record ChatRequest(ModelSnapshot Model, IReadOnlyList<ChatTurn> Turns)
{
    public IReadOnlyList<ChatTool>? Tools { get; init; }

    public bool HasTools => Tools is { Count: > 0 };
}

public abstract record ChatStreamEvent
{
    private ChatStreamEvent()
    {
    }

    /// <summary>The service accepted the request; first event of every stream. Diagnostic only.</summary>
    public sealed record ResponseStarted(int HttpStatus, string? ProviderRequestId) : ChatStreamEvent;

    public sealed record TextDelta(string Text) : ChatStreamEvent;

    /// <summary>
    /// A reasoning model sent part of its reasoning (<c>reasoning_content</c>) instead of answer text. A running answer shows
    /// it live and never stores it (requirements §10.4.4 v0.21); every other request ignores it.
    /// </summary>
    public sealed record ReasoningDelta(string Text) : ChatStreamEvent
    {
        public int Characters => Text.Length;
    }

    /// <summary>
    /// The provider declared the answer finished. <paramref name="Truncated"/> when it stopped before the answer was whole:
    /// at the output limit, or (<paramref name="Filtered"/>, health check 2026-11-12) because its content filter stopped it.
    /// </summary>
    public sealed record Completed(bool Truncated, bool Filtered = false) : ChatStreamEvent;

    /// <summary>
    /// The model asked for these tool calls (phase 2): sent once, after the last delta of the reply and before
    /// <see cref="Completed"/>. Streamed argument fragments are already joined. <paramref name="Reasoning"/> is the reasoning
    /// the service sent in this reply, to be handed back with the calls in later requests of the run; null when there was none.
    /// </summary>
    public sealed record ToolCalls(IReadOnlyList<ChatToolCall> Calls, string? Reasoning) : ChatStreamEvent;

    /// <summary>Token counts the service reported, if it did (usually with the last chunk). Diagnostic only.</summary>
    public sealed record Usage(int? PromptTokens, int? CompletionTokens) : ChatStreamEvent;
}

public sealed class ChatClientException : Exception
{
    public ChatClientException(GenerationErrorKind kind, string detail, Exception? inner = null, int? httpStatus = null)
        : base(detail, inner)
    {
        Kind = kind;
        HttpStatus = httpStatus;
    }

    public ChatClientException()
    {
    }

    public ChatClientException(string message)
        : base(message)
    {
    }

    public ChatClientException(string message, Exception innerException)
        : base(message, innerException)
    {
    }

    public GenerationErrorKind Kind { get; } = GenerationErrorKind.InvalidResponse;

    /// <summary>The service's HTTP status when it answered with an error; null for transport failures.</summary>
    public int? HttpStatus { get; }

    /// <summary>How long the service asked to wait before trying again (<c>Retry-After</c>), when it said.</summary>
    public TimeSpan? RetryAfter { get; init; }

    /// <summary>
    /// Whether trying the same request again may well succeed (docs/design/agent-loop.md L5): the connection failed or stalled,
    /// the service failed (5xx) or asked to slow down (429). Never a refused key, a used-up quota (402), a refused request or
    /// a content filter.
    /// </summary>
    public bool IsTransient => Kind switch
    {
        GenerationErrorKind.Network or GenerationErrorKind.Timeout or GenerationErrorKind.ServerError => true,
        GenerationErrorKind.QuotaOrRateLimited => HttpStatus == 429,
        _ => false,
    };
}

/// <summary>
/// Streams one completion. Throws <see cref="ChatClientException"/> for provider and transport failures; its
/// message is already redacted and safe to store or show.
/// </summary>
public interface IChatClient
{
    IAsyncEnumerable<ChatStreamEvent> StreamAsync(ChatRequest request, string apiKey, CancellationToken cancellationToken);

    /// <summary>Lists model identifiers the service reports. Does not generate and should not be billed.</summary>
    Task<IReadOnlyList<string>> ListModelsAsync(string baseUrl, string apiKey, CancellationToken cancellationToken);
}
